import numpy as np
from scipy.optimize import minimize

# Objective function
def objective(X):
    x, y, z, w = X
    return x**4 + y**4 + z**4 + w**4 - 8 * (x**3 + y**3 + z**3 + w**3)

# Constraints
# Constraint 1: x + y + z + w = 12
def constraint1(X):
    return X[0] + X[1] + X[2] + X[3] - 12

# Constraint 2: x^2 + y^2 + z^2 + w^2 = 48
def constraint2(X):
    return X[0]**2 + X[1]**2 + X[2]**2 + X[3]**2 - 48

constraints = [
    {'type': 'eq', 'fun': constraint1},
    {'type': 'eq', 'fun': constraint2}
]

# Initial guesses
initial_guesses = [
    np.array([3, 3, 3, 3]),        # Uniform guess
    np.array([6, 2, 2, 2]),        # W3's boundary guess
    np.array([10, 1, 0, 1]),       # Highly asymmetric guess
    np.array([2, 2, 4, 4])         # Intermediate guess
]

results = []
print("--- Optimization Results ---")
for i, x0 in enumerate(initial_guesses):
    try:
        result = minimize(objective, x0, method='SLSQP', constraints=constraints)
        if result.success:
            results.append(result.fun)
            print(f"Run {i+1} (Start: {x0}) -> Success. Minimum value: {result.fun:.1f}")
        else:
            print(f"Run {i+1} (Start: {x0}) -> Failed. Status: {result.message}")
    except Exception as e:
        print(f"Run {i+1} (Start: {x0}) -> Exception: {e}")

print("\nAll Minimum Values Found:", results)
